css:
/* Привлечение внимания к главной кнопке: блик по кнопке + лёгкий «вдох» + мягкое свечение.
   Серия идёт только под классом .is-nudging (его ставит скрипт) и она конечна: 2 цикла по 2 с.
   Цвета берутся из токенов дизайн-системы. */
:root {
  --cta-attn-dur: 2000ms;                     /* цикл: первые 45% — действие, остальное — пауза */
  --cta-attn-count: 2;                        /* dur × count ≤ 5 с (WCAG 2.2.2); при правке поменять SERIES в скрипте */
  --cta-attn-ease: cubic-bezier(.4, 0, .2, 1); /* мягкий вдох-выдох (Gentle float) */
}

/* Обёртка ровно по размеру кнопки: несёт «вдох» и слой свечения */
.cta-attn {
  position: relative; isolation: isolate;
  display: inline-flex; border-radius: var(--cta-radius, 999px);
}
/* Свечение — заранее нарисованная тень на отдельном слое: меняется только opacity */
.cta-attn::before {
  content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit; pointer-events: none;
  box-shadow:
    0 0 0 6px var(--cta-glow, color-mix(in srgb, var(--color-primary, #1d4ed8) 28%, transparent)),
    0 12px 32px -12px var(--cta-glow-shadow, color-mix(in srgb, var(--color-primary, #1d4ed8) 70%, transparent));
  opacity: 0;
  transition: opacity 150ms cubic-bezier(.2, 0, 0, 1);
}
/* Кнопка на всю ширину (телефон, финальный блок): <div class="cta-attn cta-attn--block" data-cta-attn> */
.cta-attn--block { display: flex; } .cta-attn--block .cta-attn__btn { flex: 1; }
.cta-attn__btn {
  position: relative; isolation: isolate; box-sizing: border-box;
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 48px; padding: 14px 28px; border: 0; border-radius: inherit;
  background: var(--color-primary, #1d4ed8); color: var(--color-on-primary, #ffffff);
  font: inherit; font-weight: 600; line-height: 1.2; text-decoration: none; cursor: pointer;
  transition: transform 150ms cubic-bezier(.2, 0, 0, 1);
}
.cta-attn__label { position: relative; z-index: 1; } /* надпись над бликом: контраст текста не падает */
/* Клип для блика — отдельный слой, у самой кнопки overflow не трогаем (тень и соседние рецепты целы) */
.cta-attn__shine {
  position: absolute; inset: 0; border-radius: inherit; overflow: hidden; isolation: isolate; pointer-events: none;
}
.cta-attn__shine::before {
  content: ""; position: absolute; inset: 0;
  /* Блик светлит фон под частью надписи. Светлая надпись: .18 гарантированно держит контраст ≥ 4.5:1 в пике
     при on_primary/primary ≥ 7:1; ниже — --cta-shine: transparent (останутся вдох и свечение).
     Тёмная надпись на светлой кнопке: --cta-shine: rgba(255,255,255,.6) — блик только поднимает контраст. */
  background: linear-gradient(105deg, transparent 38%, var(--cta-shine, rgba(255, 255, 255, .18)) 50%, transparent 62%);
  transform: translateX(-100%); /* в покое блик спрятан за левым краем */
}

@media (hover: hover) {
  .cta-attn:hover::before { opacity: .6; }
}
.cta-attn__btn:focus-visible { outline: 3px solid var(--color-text, #111827); outline-offset: 4px; }
.cta-attn__btn:active { transform: scale(.97); }

/* Серия: три анимации одной длины стартуют вместе с классом и идут синхронно */
.cta-attn.is-nudging { animation: cta-attn-breathe var(--cta-attn-dur) var(--cta-attn-ease) var(--cta-attn-count); }
.cta-attn.is-nudging::before { animation: cta-attn-glow var(--cta-attn-dur) var(--cta-attn-ease) var(--cta-attn-count); }
.cta-attn.is-nudging .cta-attn__shine::before { animation: cta-attn-shine var(--cta-attn-dur) var(--cta-attn-ease) var(--cta-attn-count); }

@keyframes cta-attn-breathe {
  0%, 45%, 100% { transform: scale(1); }
  20% { transform: scale(1.03); }
}
@keyframes cta-attn-glow {
  0%, 50%, 100% { opacity: 0; }
  20% { opacity: 1; }
}
@keyframes cta-attn-shine {
  0% { transform: translateX(-100%); }
  45%, 100% { transform: translateX(100%); }
}

@media (prefers-reduced-motion: reduce) {
  /* Убираем: «вдох» и проезд блика — это движение.
     Смягчаем: остаётся только свечение (opacity), без сдвига.
     Оставляем: рамку фокуса и свечение при наведении. */
  .cta-attn.is-nudging,
  .cta-attn.is-nudging .cta-attn__shine::before { animation: none; }
  .cta-attn__btn, .cta-attn__btn:active { transform: none; transition: none; }
}

/* Высокая контрастность Windows: блик и свечение не нужны, остаётся системная кнопка */
@media (forced-colors: active) {
  .cta-attn::before, .cta-attn__shine { display: none; }
}

js:
// Привлечение внимания к главной кнопке. Подключать в конце <body> или с defer, без зависимостей.
// Серия (2 цикла по 2 с, короче 5 с) идёт один раз на кнопку и только когда кнопка спокойно в кадре.
(() => {
  const DELAY = 3500;  // сколько кнопка должна пробыть в кадре до серии, мс
  const SERIES = 4000; // = --cta-attn-dur × --cta-attn-count из CSS; таймер ещё и жёсткий потолок серии
  const items = [...document.querySelectorAll('[data-cta-attn]')].slice(0, 2); // не больше двух кнопок
  if (!items.length || !('IntersectionObserver' in window)) return;
  const timers = new Map();
  const ac = new AbortController(); // одним abort() снимаем все слушатели
  let playing = null;
  const clear = (el) => { clearTimeout(timers.get(el)); timers.delete(el); };
  const done = (el) => { // больше эта кнопка не подмигивает до перезагрузки страницы
    clear(el); io.unobserve(el);
    el.classList.remove('is-nudging'); el.dataset.ctaAttn = 'done';
    if (playing === el) playing = null;
    if (items.every((i) => i.dataset.ctaAttn === 'done')) { io.disconnect(); ac.abort(); } // всё отыграно — наблюдатель и слушатели отключены
  };
  const arm = (el) => { clear(el); timers.set(el, setTimeout(() => play(el), DELAY)); };
  const play = (el) => {
    if (el.dataset.ctaAttn === 'done') return;
    if (document.hidden || playing) return arm(el); // вкладка в фоне или играет другая кнопка — ждём
    playing = el;
    el.classList.add('is-nudging');
    timers.set(el, setTimeout(() => done(el), SERIES + 100));
  };
  const io = new IntersectionObserver((entries) => entries.forEach((e) => {
    const el = e.target;
    if (el === playing) return; // начатую серию не обрываем: она короче 5 с
    if (e.isIntersecting && e.intersectionRatio >= 0.6) { if (!timers.has(el)) arm(el); }
    else clear(el); // ушла из кадра — отсчёт начнётся заново
  }), { threshold: 0.6 });
  items.forEach((el) => {
    io.observe(el);
    ['pointerenter', 'focusin', 'click'].forEach((t) => el.addEventListener(t, () => done(el), { signal: ac.signal }));
  });
  document.addEventListener('focusin', (e) => { // человек заполняет форму — не отвлекаем
    if (e.target.matches && e.target.matches('input, textarea, select')) items.forEach((el) => done(el));
  }, { signal: ac.signal });
})();
